<script setup lang="ts">
import { watch, ref, computed } from 'vue'
import { Heart, RefreshCw } from '@lucide/vue'
import { api, patch, post } from '../lib/api'
import { date, confirmAction, notify, run } from '../lib/ui'
const props=defineProps<{scope:string;compact?:boolean;refresh?:boolean}>()
type MoodState={value:number;emotions:Record<string,number>;enabled:boolean;revision:number;last_error:string}
type Entry={id:string;status:string;reason:string;confidence:number;delta:number;value:number;significant:boolean;injected_at:number|null;consumed_at:number|null;created_at:number}
const data=ref<{state:MoodState;events:Entry[];allowed:boolean}|null>(null),error=ref(''),busy=ref(false)
let sequence=0
const emotions=[['happy','开心'],['calm','踏实'],['sweet','甜蜜'],['heartache','心疼'],['worry','担心'],['sad','难过'],['jealous','小别扭']]
const visible=computed(()=>data.value?.events.filter(e=>e.status!=='unchanged').slice(0,12)||[])
const labels:Record<string,string>={applied:'已更新',uncertain:'依据不足 · 未影响心情',failed:'判断未完成',discarded:'配置或会话已变化',judging:'判断中'}
async function load(){const seq=++sequence;error.value='';try{const value=await api<typeof data.value>(`/mood/${encodeURIComponent(props.scope)}`);if(seq===sequence)data.value=value}catch(e){if(seq===sequence)error.value=e instanceof Error?e.message:'读取失败'}}
watch(()=>props.scope,()=>{data.value=null;load()},{immediate:true})
watch(()=>props.refresh,v=>{if(v===false)load()})
async function toggle(e:Event){if(!data.value)return;(e.target as HTMLInputElement).checked=data.value.state.enabled;busy.value=true;const scope=props.scope;try{const value=await patch(`/mood/${encodeURIComponent(props.scope)}`,{enabled:!data.value.state.enabled,revision:data.value.state.revision});if(scope===props.scope)data.value=value;notify('会话心情开关已保存')}finally{busy.value=false}}
function reset(){const scope=props.scope;confirmAction('让心情回到平稳？','恢复这个会话的基线和情绪值，已有时间线保留。',async()=>{await post(`/mood/${encodeURIComponent(scope)}/reset`);if(scope===props.scope)await load();notify('心情已回稳')})}
</script>
<template><details class="mood-panel" :class="{'mood-compact':compact}" :open="!compact"><summary><Heart :size="17" /><span>此刻的心情</span><span v-if="data" class="mood-summary">{{data.allowed&&data.state.enabled?`${Math.round(data.state.value)} · 慢慢感受`:'尚未开启'}}</span></summary><div class="mood-content"><p v-if="error" class="form-error" role="alert">{{error}}</p><template v-if="data"><div class="section-heading"><div><strong class="mood-value">{{Math.round(data.state.value)}}<small>/ 100</small></strong><p class="muted small">随时间逐渐回稳，每个会话单独保存。</p></div><button class="icon-button" aria-label="刷新心情" @click="load"><RefreshCw :size="17" /></button></div><label class="config-check"><input type="checkbox" :checked="data.state.enabled" :disabled="busy" @change="run(()=>toggle($event))" />这个会话允许心情变化</label><p v-if="!data.allowed" class="muted small">需要在<RouterLink to="/settings?tab=features">功能与权限</RouterLink>允许对应的个人或群聊心情，并在心情设置开启总开关。</p><div class="emotion-grid"><div v-for="[key,label] in emotions" :key="key"><span>{{label}}<small>{{Math.round(data.state.emotions[key!]||0)}}</small></span><meter min="0" max="100" :value="data.state.emotions[key!]||0" :aria-label="label"></meter></div></div><p v-if="data.state.last_error" class="muted small">{{data.state.last_error}}</p><details class="mood-timeline"><summary>最近的心情变化</summary><p v-if="!visible.length" class="muted small">还没有明显变化。普通交流也可以保持平稳。</p><article v-for="e in visible" :key="e.id"><div><time>{{date(e.created_at)}}</time><span>{{labels[e.status]||e.status}}<template v-if="e.status==='applied'"> · {{e.delta>0?'+':''}}{{e.delta.toFixed(1)}}</template></span></div><p>{{e.reason||'正在理解这次交流'}}</p><small v-if="e.status==='applied'">{{e.injected_at?'已用于语气参考':e.consumed_at?'已随更新归档':e.significant?'等待合适的下一轮':'小波动，仅记录'}} · 置信度 {{Math.round(e.confidence*100)}}%</small></article></details><div class="config-form-actions"><RouterLink to="/settings?tab=activities" class="text-link">心情设置</RouterLink><button class="text-link" :disabled="busy" @click="reset">回到平稳</button></div></template></div></details></template>
<style scoped>
.mood-panel{border:1px solid #DDD1E9;border-radius:18px;background:linear-gradient(120deg,#F7F6F5,#F0DFEA66);margin:16px 0;color:#403947}.mood-panel>summary{display:flex;align-items:center;gap:10px;cursor:pointer;padding:17px 20px;font-weight:600}.mood-summary{margin-left:auto;font-size:12px;font-weight:400;color:#74697d}.mood-content{padding:0 20px 18px}.mood-value{font-size:34px;font-weight:600;color:#76618b}.mood-value small{font-size:13px;color:#8a8090;margin-left:5px}.emotion-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:14px;margin:20px 0}.emotion-grid span{display:flex;justify-content:space-between;font-size:12px}.emotion-grid small{color:#8a8090}.emotion-grid meter{width:100%;height:8px;appearance:none}.emotion-grid meter::-webkit-meter-bar{background:#DDD1E955;border:0;border-radius:8px}.emotion-grid meter::-webkit-meter-optimum-value{background:linear-gradient(90deg,#A4B5D5,#EABCDD);border-radius:8px}.mood-timeline>summary{cursor:pointer;font-size:13px;color:#76618b}.mood-timeline article{padding:12px 0;border-bottom:1px solid #DDD1E966}.mood-timeline article>div{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#817486}.mood-timeline article p{font-size:13px;line-height:1.7;margin:8px 0}.mood-timeline article small{font-size:11px;color:#817486}.mood-compact{margin:0 20px 8px;flex-shrink:0}.mood-compact>summary{padding:9px 14px;font-size:12px}.mood-compact[open]{max-height:330px;overflow:auto}@media(max-width:600px){.mood-summary{max-width:150px;text-align:right}.mood-timeline article>div{flex-wrap:wrap}}
</style>
